procedure BowlingOutreachCampaign {
  about "On request, contact recent quit bowlers"
  policy BowlingPolicy
  sheet Leagues "Leagues" { bowler: Text, phone: Phone, next_game: DateTime, status: Text, dues: Money, shoe_size_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Leagues
  let targets = filter all where status == "quit" and days_between(next_game, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft sms to r.phone: "Hi {r.bowler default 'there'}, come back to the alley! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

